{
  "name": "Hamilton 微孔板加热振荡器控制盒",
  "name_en": "Hamilton Heater Shaker Box",
  "manufacturer": "Hamilton",
  "description": "用于连接和控制 Hamilton 微孔板加热振荡器的控制盒，可执行加热、振荡、锁板/解锁并读取温度信息，常用于微孔板样品的孵育、混匀和自动化实验流程。",
  "description_en": "A control box for Hamilton microplate heater-shaker units, used to heat and shake plates, lock or release plates, and read temperature information. It is commonly used for plate incubation, mixing, and automated laboratory workflows.",
  "tag_hints": [
    "microplate heating",
    "plate shaking",
    "sample incubation",
    "plate locking",
    "temperature control",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-send_hhs_command",
      "description": "向加热振荡器控制器发送原始命令。",
      "description_en": "Send a raw command to the heater-shaker controller."
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "获取是否支持主动冷却。",
      "description_en": "Get whether active cooling is supported."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出设备标识与配置信息。",
      "description_en": "Serialize the device identity and configuration."
    },
    {
      "action_name": "auto-shake",
      "description": "启动微孔板振荡混匀。",
      "description_en": "Start shaking the microplate."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-get_is_shaking",
      "description": "获取是否正在振荡。",
      "description_en": "Get whether the device is shaking."
    },
    {
      "action_name": "auto-supports_locking",
      "description": "获取是否支持锁板功能。",
      "description_en": "Get whether plate locking is supported."
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定微孔板。",
      "description_en": "Lock the microplate in place."
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁微孔板。",
      "description_en": "Unlock the microplate."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置目标温度。",
      "description_en": "Set the target temperature."
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    },
    {
      "action_name": "auto-get_edge_temperature",
      "description": "获取边缘温度。",
      "description_en": "Get the edge temperature."
    },
    {
      "action_name": "auto-deactivate",
      "description": "停用设备并关闭当前活动功能。",
      "description_en": "Deactivate the device and stop active functions."
    }
  ]
}

